def solve(s: str) -> int:
    """Convert a Roman numeral to an integer. Handles standard subtractive notation.
    Assumes input is a valid Roman numeral consisting of characters I,V,X,L,C,D,M.
    """
    values = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        if i+1 < n and values[s[i]] < values[s[i+1]]:
            total += values[s[i+1]] - values[s[i]]
