def solve(tokens):
    stack = []
    for t in tokens:
        if t in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # '/'
                # Truncate toward zero
                res = int(a / b)  # Python int truncates toward zero for division of ints via float
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

