def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    tokens: list of strings, each either an integer or one of '+', '-', '*', '/'.
    Division truncates toward zero as in the problem statement.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Python's int division truncates toward negative infinity for //, so use int(a / b)
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

