def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting algorithm with binary search.
    """
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = min possible tail of an increasing subseq of length i+1
    for x in nums:
        # find insertion point
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

